function validateFinite(value, name) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${name} must be a finite number`);
  }
}

function validateNonNegative(value, name) {
  validateFinite(value, name);
  if (value < 0) {
    throw new RangeError(`${name} must not be negative`);
  }
}

/** Exact international mile definition: 1 mile = 1.609344 km */
const KM_PER_MILE = 1.609344;

/** Exact avoirdupois pound definition: 1 lb = 0.45359237 kg */
const KG_PER_POUND = 0.45359237;

export function kmToMiles(km) {
  validateNonNegative(km, 'km');
  return km / KM_PER_MILE;
}

export function celsiusToFahrenheit(celsius) {
  validateFinite(celsius, 'celsius');
  return (celsius * 9) / 5 + 32;
}

export function kgToPounds(kg) {
  validateNonNegative(kg, 'kg');
  return kg / KG_PER_POUND;
}

